#addSyncAccounts(syncAccounts) {
  for (const calendar of syncAccounts.calendars) {
    lazy.cal.manager.registerCalendar(calendar);
  }

  for (const addressBook of syncAccounts.addressBooks) {
    addressBook.create();
  }

// Trigger the initial sync with the server. Do not do this async,
// as it's not required before returning the directory.
authPromise.then(() => dir.fetchAllFromServer()).catch(console.error);

return dir;
